class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class TreeNode:
    def __init__(self, data):
        self.data, self.left, self.right = data, None, None

def sortedListToBST(head):
    if not head:
        return None

    nodes = []
    curr = head
    while curr:
        nodes.append(curr.data)
        curr = curr.next

    def buildBST(start, end):
        if start > end:
            return None

        mid = (start + end) // 2
        root = TreeNode(nodes[mid])
        root.left = buildBST(start, mid - 1)
        root.right = buildBST(mid + 1, end)
        return root

    return buildBST(0, len(nodes) - 1)

import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    values = [int(x) for x in input_data[1:n+1]]

    if not values:
        return

    head = Node(values[0])
    curr = head
    for val in values[1:]:
        curr.next = Node(val)
        curr = curr.next

    root = sortedListToBST(head)

    result = []
    def preorder(node):
        if not node:
            return
        result.append(str(node.data))
        preorder(node.left)
        preorder(node.right)

    preorder(root)
    sys.stdout.write(" ".join(result) + "\n")

if __name__ == "__main__":
    main()
